def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me, last_opp = history[-1]

    total_opp_d = opp.count('D')
    total_opp_c = n - total_opp_d

    # Unconditional cooperator: exploit late, but not too early
    if total_opp_d == 0:
        if n >= 92:
            return 'D'
        if n >= 60 and n % 13 == 0:
            return 'D'
        return 'C'

    # Unconditional defector
    if total_opp_c == 0:
        return 'D'

    # Extremely defective opponent: minimize losses
    if total_opp_d * 4 >= n * 3:
        if n >= 4 and opp[-3:].count('C') >= 2:
            return 'C'
        return 'D'

    # Slightly forgiving TFT core with adaptive response
    # Examine opponent's response to our defections vs cooperations
    opp_after_my_C_D = 0
    opp_after_my_C = 0
    opp_after_my_D_D = 0
    opp_after_my_D = 0
    for i in range(n - 1):
        if me[i] == 'C':
            opp_after_my_C += 1
            if opp[i + 1] == 'D':
                opp_after_my_C_D += 1
        else:
            opp_after_my_D += 1
            if opp[i + 1] == 'D':
                opp_after_my_D_D += 1

    # If opponent tends to punish our defection (TFT-like), cooperate
    if opp_after_my_D > 0:
        punish_rate = opp_after_my_D_D / opp_after_my_D
    else:
        punish_rate = 0.0
    if opp_after_my_C > 0:
        base_d_rate = opp_after_my_C_D / opp_after_my_C
    else:
        base_d_rate = 0.0

    # If opponent cooperates after our D more than after our C: they are forgiving/exploitable
    if opp_after_my_D >= 3 and opp_after_my_C >= 2:
        if base_d_rate > punish_rate + 0.25 and n > 15:
            # Exploit: defect frequently but occasionally cooperate to keep them around
            if rng.random() < 0.75:
                return 'D'
            return 'C'

    # If opponent punishes strongly (TFT-like), just cooperate to maintain CC
    if opp_after_my_D >= 3 and punish_rate > 0.85:
        # Recover to cooperation
        if last_opp == 'D' and opp[-2:].count('D') >= 2:
            return 'D'
        if last_me == 'D' and last_opp == 'D':
            return 'C'
        return 'C'

    # Detect defect streaks
    recent5 = opp[-5:] if n >= 5 else opp
    opp_recent_d = recent5.count('D')

    # Opponent in defect streak -> punish
    if opp_recent_d >= 4:
        return 'D'

    # Opponent very cooperative recently
    if opp_recent_d == 0:
        # Exploit at very end
        if n >= 95:
            return 'D'
        # Rare early probe only if opponent has been generous
        if n >= 30 and total_opp_c >= n - 2 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Standard TFT: mirror last action with slight forgiveness
    if last_opp == 'D':
        # If opponent rarely defects overall, forgive
        if total_opp_d * 5 < n and n > 8:
            if rng.random() < 0.7:
                return 'C'
        # Escalate if consecutive defections
        if n >= 2 and opp[-2] == 'D':
            return 'D'
        return 'D'

    # Opponent cooperated last
    # End-game exploitation only if opponent hasn't punished us
    if n >= 96:
        return 'D'
    if n >= 90 and total_opp_d <= 2:
        return 'D'
    return 'C'
